import React, { useState } from 'react';
import './App.css'; // Cargamos tus nuevos estilos impecables

function App() {
  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [imagenUrl, setImagenUrl] = useState('https://www.bing.com/images/search?view=detailV2&ccid=PKW%2Ff');
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState(2400);
  const [stock, setStock] = useState(20);

  const porcentajeIVA = parseFloat(impuesto) / 100;
  const costoConIVA = precioCosto * (1 + porcentajeIVA);
  const margenSugerido = costoConIVA * 1.30;

  const formatearMoneda = (valor) => {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0
    }).format(valor);
  };

  const handleGuardar = async (e) => {
    e.preventDefault();
    const nuevoProducto = {
      nombre,
      categoria,
      imagenUrl,
      precioCosto: parseFloat(precioCosto),
      impuesto: parseFloat(impuesto),
      precioVenta: parseFloat(precioVenta),
      stock: parseInt(stock)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert("¡Producto guardado en la base de datos el_paisita_up!");
      } else {
        alert("El servidor respondió, pero hubo un problema al guardar.");
      }
    } catch (error) {
      alert("No se pudo conectar con el servidor de Java. ¡Asegúrate de que Spring Boot esté corriendo!");
    }
  };

  return (
    <div>
      {/* Botones de navegación superiores */}
      <div className="nav-container">
        <button className="btn-nav-inventario">📦 Ver Inventario</button>
        <button className="btn-nav-salir">🚪 Salir</button>
      </div>

      {/* Tarjeta Contenedora Principal */}
      <div className="form-card">
        <h2 className="form-title">
          Ingreso de Mercancía <span>(distribuidor)</span>
        </h2>

        <form onSubmit={handleGuardar}>
          <div className="form-group">
            <label className="form-label">Nombre del Producto</label>
            <input type="text" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" />
          </div>

          <div className="form-group">
            <label className="form-label">Categoría</label>
            <input type="text" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" />
          </div>

          <div className="form-group">
            <label className="form-label">Imagen (URL)</label>
            <input type="text" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} className="form-input" />
          </div>

          <div className="form-row">
            <div>
              <label className="form-label">Precio Costo</label>
              <input type="number" value={precioCosto} onChange={(e) => setPrecioCosto(Number(e.target.value))} className="form-input" />
            </div>
            <div>
              <label className="form-label">Impuesto</label>
              <select value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input">
                <option value="19">IVA 19% (General CO)</option>
                <option value="8">INC 8% (Consumo)</option>
                <option value="0">Exento</option>
              </select>
            </div>
          </div>

          {/* Caja del Margen Sugerido */}
          <div className="suggested-box">
            <p className="suggested-title">Costo con IVA + Margen Sugerido (30% Generado)</p>
            <div className="suggested-price">{formatearMoneda(margenSugerido)}</div>
          </div>

          <div className="form-row">
            <div>
              <label className="form-label">Precio Venta</label>
              <input type="number" value={precioVenta} onChange={(e) => setPrecioVenta(Number(e.target.value))} className="form-input" />
            </div>
            <div>
              <label className="form-label">Stock Inicial</label>
              <input type="number" value={stock} onChange={(e) => setStock(Number(e.target.value))} className="form-input" />
            </div>
          </div>

          <button type="submit" className="btn-submit">
            Meter a la Base de Datos
          </button>
        </form>
      </div>
    </div>
  );
}

export default App;
